-- A period may cap how many OPEN or PENDING claims each person has in it (null: no cap). Opening a claim that belongs
-- to the period (its due-by falls in it) is refused once its person has that many. Kept in the period's history too
-- (see V40). The journal trigger is made again around the change, as in V65.
DROP TRIGGER period_journal;
ALTER TABLE period ADD COLUMN claim_cap INT;
ALTER TABLE period_history ADD COLUMN claim_cap INT;
CREATE TRIGGER period_journal AFTER INSERT, UPDATE, DELETE ON period FOR EACH ROW CALL 'net.officefloor.hq.app.history.Journal';
import { useSyncExternalStore } from 'react';

// The date this user's screen is shown as of (yyyy-mm-dd), '' when it shows the sheet as it is now. It
// belongs to this screen only: every request names it (X-As-Of, see http.ts), so the server answers a read
// as the store stood at the end of that date and refuses every change while it is set.
let asOf = '';
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** The as-of date the requests name now ('' for none, and while `withoutAsOf` runs). */
export function currentAsOf(): string {
  return ignoring > 0 ? '' : asOf;
}

// While above 0, requests made name no as-of date: they read the sheet as it is now.
let ignoring = 0;

/** Runs the work with the requests it makes (synchronously) reading the sheet as it is now, whatever the as-of date. */
export function withoutAsOf<T>(work: () => T): T {
  ignoring++;
  try {
    return work();
  } finally {
    ignoring--;
  }
}

export function setAsOf(date: string): void {
  if (asOf === date) return;
  asOf = date;
  listeners.forEach((l) => l());
}

/** The as-of date shown on this screen ('' for none). */
export function useAsOf(): string {
  return useSyncExternalStore(subscribe, () => asOf);
}
import { QueryClient } from '@tanstack/react-query';
import { withoutAsOf } from '../api/asOf';

/**
 * A query client of its own whose queries read the sheet as it is now, even while the screen is shown as of a date:
 * every query function it runs makes its requests without the as-of date. Same defaults as the app's client.
 */
export function nowQueryClient(): QueryClient {
  const client = new QueryClient({
    defaultOptions: {
      queries: { retry: false, refetchOnWindowFocus: false },
      mutations: { retry: false },
    },
  });
  const defaulted = client.defaultQueryOptions.bind(client);
  client.defaultQueryOptions = ((options: Parameters<typeof defaulted>[0]) => {
    const o = defaulted(options);
    const fn = o.queryFn;
    if (typeof fn === 'function') {
      o.queryFn = (context: Parameters<typeof fn>[0]) => withoutAsOf(() => fn(context));
    }
    return o;
  }) as typeof client.defaultQueryOptions;
