      />{' '}
      <button type="submit" data-testid="asof-set">
        Show as of
      </button>{' '}
      <button
        type="button"
        data-testid="asof-clear"
        onClick={() => {
          setError('');
          setTyped('');
          show('');
        }}
      >
        Show now
      </button>
      {error && <p data-testid="asof-error">{error}</p>}
    </form>
  );
}

